// Sieve of Eratosthenes: fill `primes` with the first 100 primes and
// return the 100th (541). No multiply or divide needed.
#define LIMIT 560
static unsigned char composite[LIMIT + 1];
unsigned int primes[100];

int main(void) {
    for (int i = 2; i + i <= LIMIT; i++) {
        if (composite[i]) continue;
        for (int j = i + i; j <= LIMIT; j += i) composite[j] = 1;
    }
    int n = 0;
    for (int i = 2; i <= LIMIT && n < 100; i++)
        if (!composite[i]) primes[n++] = i;
    return primes[99];
}

// Recursive Lomuto quicksort on 16 words in place. Exercises stack frames
// (sp/ra save and restore), recursive jal/jalr redirects, and load-use stalls
// during partition scans. Returns the median-pair sum data[7] + data[8] = 760.
unsigned int data[16] = {
    907, 23, 611, 404, 77, 999, 150, 3,
    862, 512, 48, 730, 265, 191, 638, 356
};
unsigned int swaps;
unsigned int partitions;

static void qsort_range(int lo, int hi) {
    if (lo >= hi) return;
    partitions++;
    unsigned int pivot = data[hi];
    int i = lo;
    for (int j = lo; j < hi; j++) {
        if (data[j] < pivot) {
            unsigned int t = data[i];
            data[i] = data[j];
            data[j] = t;
            i++;
            swaps++;
        }
    }
    unsigned int t = data[i];
    data[i] = data[hi];
    data[hi] = t;
    swaps++;
    qsort_range(lo, i - 1);
    qsort_range(i + 1, hi);
}

int main(void) {
    qsort_range(0, 15);
    return (int)(data[7] + data[8]);
}

// O(log n) 2x2 matrix exponentiation for Fibonacci: [1 1; 1 0]^30.
// On base RV32I (without M), each multiply calls libgcc __mulsi3, showing
// why algorithmic O(log n) with software multiply costs more cycles than
// O(n) iterative additions for n = 30. Returns fib(30) = 832040.
unsigned int mat_result[4];

static void mat_mul(unsigned int c[4], const unsigned int a[4], const unsigned int b[4]) {
    unsigned int c0 = a[0] * b[0] + a[1] * b[2];
    unsigned int c1 = a[0] * b[1] + a[1] * b[3];
    unsigned int c2 = a[2] * b[0] + a[3] * b[2];
    unsigned int c3 = a[2] * b[1] + a[3] * b[3];
    c[0] = c0; c[1] = c1; c[2] = c2; c[3] = c3;
}

int main(void) {
    unsigned int res[4]  = { 1, 0, 0, 1 };
    unsigned int base[4] = { 1, 1, 1, 0 };
    int n = 30;
    while (n > 0) {
        if (n & 1) mat_mul(res, res, base);
        mat_mul(base, base, base);
        n >>= 1;
    }
    for (int i = 0; i < 4; i++) mat_result[i] = res[i];
    return (int)res[1];
}

// Iterative Fibonacci: fib[0..31] in memory, return fib(30) = 832040.
unsigned int fib[32];

int main(void) {
    fib[0] = 0; fib[1] = 1;
    for (int i = 2; i < 32; i++) fib[i] = fib[i - 1] + fib[i - 2];
    return fib[30];
}

// Binary GCD (Stein's algorithm) over a table of pairs; results stored
// next to the inputs. Returns gcd(1071, 462) = 21.
struct pair { unsigned a, b, g; };
struct pair table[6] = {
    {1071, 462, 0}, {48, 18, 0}, {270, 192, 0}, {65536, 4096, 0}, {17, 5, 0}, {600851475, 25, 0},
};

static unsigned gcd(unsigned a, unsigned b) {
    if (a == 0) return b;
    if (b == 0) return a;
    int shift = 0;
    while (((a | b) & 1) == 0) { a >>= 1; b >>= 1; shift++; }
    while ((a & 1) == 0) a >>= 1;
    while (b) {
        while ((b & 1) == 0) b >>= 1;
        if (a > b) { unsigned t = a; a = b; b = t; }
        b -= a;
    }
    return a << shift;
}

int main(void) {
    for (int i = 0; i < 6; i++) table[i].g = gcd(table[i].a, table[i].b);
    return table[0].g;
}

// Bubble sort 16 words in place; watch the array reorder in memory.
// Returns the number of swaps performed.
unsigned int data[16] = { 907, 23, 611, 404, 77, 999, 150, 3, 862, 512, 48, 730, 265, 191, 638, 356 };

int main(void) {
    unsigned swaps = 0;
    for (int i = 0; i < 15; i++)
        for (int j = 0; j < 15 - i; j++)
            if (data[j] > data[j + 1]) {
                unsigned t = data[j]; data[j] = data[j + 1]; data[j + 1] = t;
                swaps++;
            }
    return swaps;
}

// Bitwise CRC-32 (IEEE 802.3, reflected, poly 0xEDB88320) of the message
// below. Returns the checksum; compare with zlib.crc32.
const char message[] = "Silicon RV32I five-stage pipeline";
unsigned int checksum;

int main(void) {
    unsigned crc = 0xFFFFFFFFu;
    for (const char *p = message; *p; p++) {
        crc ^= (unsigned char)*p;
        for (int k = 0; k < 8; k++) crc = (crc >> 1) ^ (0xEDB88320u & -(crc & 1));
    }
    checksum = ~crc;
    return checksum;
}

// 3x3 integer matrix product C = A*B. RV32I has no multiply instruction, so
// GCC calls libgcc's shift-and-add __mulsi3. Returns trace(C) = 175.
int A[3][3] = { {2, 7, 1}, {8, 2, 8}, {1, 8, 2} };
int B[3][3] = { {8, 4, 5}, {9, 0, 4}, {5, 2, 3} };
int C[3][3];

int main(void) {
    for (int i = 0; i < 3; i++)
        for (int j = 0; j < 3; j++) {
            int s = 0;
            for (int k = 0; k < 3; k++) s += A[i][k] * B[k][j];
            C[i][j] = s;
        }
    return C[0][0] + C[1][1] + C[2][2];
}

// Reverse a string in place, byte loads and stores. Returns its length (25).
char text[] = "the quick brown fox jumps";

int main(void) {
    int n = 0;
    while (text[n]) n++;
    for (int i = 0, j = n - 1; i < j; i++, j--) {
        char t = text[i]; text[i] = text[j]; text[j] = t;
    }
    return n;
}

// Binary search for several keys in a sorted table; each probe count is
// recorded. Returns the index of key 733 (= 21).
const unsigned table[32] = {
    2, 5, 11, 17, 23, 31, 41, 47, 59, 67, 73, 83, 97, 101, 113, 127,
    137, 149, 163, 179, 193, 733, 811, 823, 907, 947, 1013, 1061, 1123, 1187, 1259, 1301 };
const unsigned keys[4] = { 733, 2, 1301, 600 };
int found[4];
int probes[4];

int main(void) {
    for (int q = 0; q < 4; q++) {
        int lo = 0, hi = 31, idx = -1, n = 0;
        while (lo <= hi) {
            int mid = (lo + hi) >> 1;
            n++;
            if (table[mid] == keys[q]) { idx = mid; break; }
            if (table[mid] < keys[q]) lo = mid + 1; else hi = mid - 1;
        }
        found[q] = idx; probes[q] = n;
    }
    return found[0];
}

// Longest Collatz chain for starting values below 100: 97 takes 118 steps.
// Returns the start value; the step count is stored in `best_steps`.
unsigned best_start, best_steps;
unsigned steps[100];

int main(void) {
    for (unsigned n = 1; n < 100; n++) {
        unsigned x = n, s = 0;
        while (x != 1) { x = (x & 1) ? 3 * x + 1 : x >> 1; s++; }
        steps[n] = s;
        if (s > best_steps) { best_steps = s; best_start = n; }
    }
    return best_start;
}

// Fixed-point Mandelbrot set drawn as ASCII into memory (40 x 12 characters,
// one row per 40 bytes). Multiplies go through libgcc's __mulsi3. Returns the
// number of points that stayed bounded.
#define W 40
#define H 12
#define FRAC 12
char image[H][W + 1];
static const char shade[] = " .:-=+*#%@";

int main(void) {
    int inside = 0;
    for (int py = 0; py < H; py++) {
        for (int px = 0; px < W; px++) {
            int cx = -2 * (1 << FRAC) + (px * (3 * (1 << FRAC)) / W);   // -2.0 .. 1.0
            int cy = -(1 << FRAC) + (py * (2 * (1 << FRAC)) / H);       // -1.0 .. 1.0
            int x = 0, y = 0, i = 0;
            while (i < 18) {
                int xx = (x * x) >> FRAC, yy = (y * y) >> FRAC;
                if (xx + yy > (4 << FRAC)) break;
                y = ((2 * x * y) >> FRAC) + cy;
                x = xx - yy + cx;
                i++;
            }
            if (i == 18) inside++;
            image[py][px] = shade[i >= 18 ? 9 : i / 2];
        }
        image[py][W] = 0;
    }
    return inside;
}

